package br.edu.ifms.robotica.util;
import java.io.File;import java.io.IOException;import java.util.Set;import javax.servlet.http.Part;
public final class UploadUtil{private static final Set<String> TIPOS=Set.of("image/jpeg","image/png","image/webp");private UploadUtil(){}public static String salvar(Part part,String pasta,String base)throws IOException{if(part==null||part.getSize()==0)return null;if(part.getSize()>5L*1024*1024||!TIPOS.contains(part.getContentType()))throw new IllegalArgumentException("erro.foto.invalida");String original=new File(part.getSubmittedFileName()).getName();String ext=original.lastIndexOf('.')>=0?original.substring(original.lastIndexOf('.')).toLowerCase():"";String nome=java.util.UUID.randomUUID()+"-"+base.replaceAll("[^a-zA-Z0-9]","_")+ext;File dir=new File(System.getProperty("user.home"),"portal-robotica/uploads/"+pasta);if(!dir.exists()&&!dir.mkdirs())throw new IOException("Não foi possível criar a pasta de uploads.");part.write(new File(dir,nome).getAbsolutePath());return nome;}}
